SELECT set_client_scope($1::uuid);
UPDATE engine_runs SET status='SUCCEEDED', attempts=$2, completed_at=now(), input_tokens=$3, output_tokens=$4, duration_ms=$5 WHERE run_id=$6::uuid;
INSERT INTO engine_outputs (run_id, human_output, structured, control, schema_valid, handoff_tag, handoff_mode, secondary_handoffs) VALUES ($6::uuid, $7, $8::jsonb, $9::jsonb, true, $10, $11, $12::jsonb)

SELECT set_client_scope($1::uuid);
UPDATE engine_runs SET status='DEAD_LETTER', attempts=$2, completed_at=now(), input_tokens=$3, output_tokens=$4, duration_ms=$5, error_class=$6::failure_type, error_detail=$7 WHERE run_id=$8::uuid;
INSERT INTO dead_letter_jobs (job_type, entity_type, entity_id, failure_reason, raw_payload, attempts) VALUES ($9, 'engine_run', $8, $7, $10::jsonb, $2)

